((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2005-9-10","year":2005,"grades":[9,10],"label":"9–10 классы","tasksUrl":"assets/kenguru/kenguru_2005_class_9-10.pdf","answersUrl":"assets/kenguru/kenguru_2005_answers.pdf","solutionUrl":null,"answerLetters":"ABCDE","cards":[{"number":1,"title":"Кенгуру на доске","question":"Сначала восемь кенгуру сидели так, как показано на рисунке. Потом некоторые из них перепрыгнули на свободные квадратики так, что в каждой строке и каждом столбце оказалось ровно по два кенгуру. Какое наибольшее количество кенгуру при этом могли остаться на своих местах?","options":[{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"}],"condition":{"src":"assets/grades-9-10/2005/task-01.svg","width":304,"height":306,"alt":"Доска 4×4 с восемью кенгуру. Слева направо они занимают первые 3, 2, 2 и 1 клетки в рядах сверху вниз"},"answer":2,"points":3,"review":[{"title":"Решение","text":"В первом столбце из четырёх кенгуру два должны уйти, во втором из трёх должен уйти ещё один. Не больше пяти могут остаться."},{"title":"Ответ","text":"Пересадим кенгуру из (строка 1, столбец 1) в (4, 3), из (2, 1) в (2, 4) и из (3, 2) в (3, 4). В каждой строке и столбце будет по два. Значит, пять достижимо."}],"keyNote":null},{"number":2,"title":"Корень от произведения","question":"∛(x√x) равно","options":[{"text":"x^(2/3)"},{"text":"x^(1/6)"},{"text":"x^(1/3)"},{"text":"x^(1/2)"},{"text":"x^(5/6)"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Под корнем стоит x√x = x^(3/2), поскольку x ≥ 0."},{"title":"Ответ","text":"Кубический корень делит показатель на 3. Получаем x^(1/2)."}],"keyNote":null},{"number":3,"title":"Музыканты на концерте","question":"В концерте участвовали 4 солиста, 3 дуэта, 2 трио и 1 квартет. Сколько музыкантов участвовали в концерте?","options":[{"text":"10"},{"text":"16"},{"text":"20"},{"text":"24"},{"text":"30"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Четыре солиста дают 4 музыкантов, три дуэта — 6, два трио — ещё 6."},{"title":"Ответ","text":"Прибавляем квартет из четырёх. Всего 4 + 6 + 6 + 4 = 20 музыкантов."}],"keyNote":null},{"number":4,"title":"Высота к гипотенузе","question":"В прямоугольном треугольнике с катетами a и b на гипотенузу c опущена высота h. Какое соотношение обязательно верно?","options":[{"text":"ab = h²"},{"text":"a + b = c + h"},{"text":"bh = ac"},{"text":"ch = ab"},{"text":"ни одно из указанных"}],"condition":{"src":"assets/grades-9-10/2005/task-04.svg","width":210,"height":162,"alt":"Прямоугольный треугольник с катетами a и b, гипотенузой c и высотой h к ней"},"answer":3,"points":3,"review":[{"title":"Решение","text":"Вычислим площадь треугольника по двум катетам. Она равна ab/2."},{"title":"Ответ","text":"Если за основание взять гипотенузу, та же площадь равна ch/2. Отсюда ch = ab."}],"keyNote":null},{"number":5,"title":"Отпуск сотрудников","question":"Сотрудники фирмы «Бурундук» уходят в отпуск на целый месяц, если этот месяц начинается и кончается одним и тем же днем недели. Сколько месяцев будут отдыхать сотрудники фирмы с 1 января 2005 года по 31 декабря 2015 года?","options":[{"text":"0"},{"text":"1"},{"text":"2"},{"text":"11"},{"text":"132"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"От первого числа месяца до последнего проходит на один день меньше длины месяца. Чтобы дни недели совпали, разность должна делиться на 7."},{"title":"Ответ","text":"Среди длин 28, 29, 30 и 31 подходит только 29. В указанном промежутке такой февраль был в 2008 и 2012 годах. Всего два месяца."}],"keyNote":null},{"number":6,"title":"Куб натурального числа","question":"Какое из следующих чисел является кубом натурального числа?","options":[{"text":"6,4 · 10¹¹"},{"text":"6,4 · 10¹³"},{"text":"6,4 · 10¹⁴"},{"text":"6,4 · 10¹⁵"},{"text":"6,4 · 10¹⁸"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Запишем числа в виде 64 · 10^(n − 1), где n — показатель из списка. Число 64 равно 4³."},{"title":"Ответ","text":"Для полного куба показатель каждого простого множителя должен делиться на 3. Из данных n только при n = 13 число n − 1 равно 12 и делится на 3. Это куб числа 40 000."}],"keyNote":null},{"number":7,"title":"Распорядок Учёного Кота","question":"С полуночи до полудня Ученый Кот рассказывает сказки, а с полудня до полуночи — спит под дубом. На дубе том висит плакат: «Два часа назад Кот делал то же самое, что будет делать через час». В какой из указанных моментов времени надпись на плакате верна?","options":[{"text":"1:30"},{"text":"23:30"},{"text":"0:30"},{"text":"22:30"},{"text":"13:30"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Плакат сравнивает моменты на два часа раньше и на час позже указанного. Для 22:30 это 20:30 и 23:30, в обоих случаях Кот спит."},{"title":"Ответ","text":"Для 1:30, 23:30 и 0:30 один из моментов до полуночи, другой после. Для 13:30 моменты по разные стороны полудня. Подходит только 22:30."}],"keyNote":null},{"number":8,"title":"Сравнение пяти выражений","question":"Пусть x > 1 и 0 < y < 1. Какое из следующих чисел самое маленькое?","options":[{"text":"xy"},{"text":"x/y"},{"text":"y/x"},{"text":"x²/y²"},{"text":"y²/x²"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Пусть t = y/x. Тогда 0 < t < 1, значит, t² < t, а оба выражения с x/y больше 1."},{"title":"Ответ","text":"Остаётся сравнить t² с xy. Их отношение равно (y²/x²)/(xy) = y/x³ < 1. Самое маленькое число — y²/x²."}],"keyNote":null},{"number":9,"title":"Два согнутых куска проволоки","question":"Каждый из двух согнутых кусков проволоки состоит из 8 участков длины 1. Один из кусков наложили на другой так, что они частично совпали. Какова наибольшая возможная длина их общей части?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-9-10/2005/task-09.svg","width":360,"height":144,"alt":"Два куска проволоки в виде ломаных; отдельные единичные участки отмечены точками"},"answer":3,"points":3,"review":[{"title":"Решение","text":"На левой проволоке четыре горизонтальных и четыре вертикальных звена. Чтобы совпало больше четырёх единиц, нужны совпадения в обоих направлениях. Тогда проволоки лежат на общей единичной сетке с целым сдвигом."},{"title":"Проверка","text":"Проверим целые сдвиги, совмещая по одному звену одинакового направления. Максимумы при поворотах на 0°, 90°, 180° и 270° равны 4, 5, 3 и 4. После зеркального отражения они равны 4, 2, 4 и 3."},{"title":"Ответ","text":"Поворот на 90° позволяет совместить пять последовательных звеньев левой проволоки со второго по шестое. Это наибольшая общая длина."}],"keyNote":null},{"number":10,"title":"Квадраты синусов и косинусов","question":"Пусть A = sin² α + sin² β, B = cos² α + cos² β. Какой из вариантов возможен?","options":[{"text":"A = 1, B = 3/2"},{"text":"A = 3/4, B = 5/4"},{"text":"A = 3/2, B = 4/3"},{"text":"A = 2, B = 2"},{"text":"никакой из перечисленных"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Из sin² t + cos² t = 1 получаем A + B = 2. Только во втором варианте сумма равна 2."},{"title":"Ответ","text":"Он осуществим при α = 60° и β = 0°. Тогда A = 3/4, B = 1/4 + 1 = 5/4."}],"keyNote":null},{"number":11,"title":"Следующий квадрат","question":"Если x — квадрат натурального числа, то следующий квадрат натурального числа — это","options":[{"text":"x + 1"},{"text":"x² + 1"},{"text":"x² + 2x + 1"},{"text":"x² + x"},{"text":"x + 2√x + 1"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Если x = n², следующий квадрат получается при числе n + 1."},{"title":"Ответ","text":"Раскрываем (n + 1)² = n² + 2n + 1. Подставив n = √x, получаем x + 2√x + 1."}],"keyNote":null},{"number":12,"title":"Буквы слова «число»","question":"Жан-Кристоф продолжает изучать русский язык. Он выписывает подряд натуральные числа словами до тех пор, пока не напишет первое число, в записи которого участвуют все буквы слова «число». Чему равна сумма цифр числа, на котором Жан-Кристоф остановится?","options":[{"text":"5"},{"text":"8"},{"text":"9"},{"text":"11"},{"text":"30"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Нужны буквы с, л, о и в. До миллиона ни одно название разряда, ни одно слово для сотен, десятков или единиц не содержит л. В слове «миллион» эта буква есть."},{"title":"Ответ","text":"Буквы с и в впервые добавляет слово «восемь». Подходит 1000008 — «один миллион восемь». Сумма цифр равна 9."}],"keyNote":null},{"number":13,"title":"Три полуокружности","question":"На рисунке изображены три полуокружности радиуса 2. Точки A и B расположены в точности над центрами E и F двух нижних полуокружностей. Чему равна площадь закрашенной области?","options":[{"text":"2π"},{"text":"7"},{"text":"2π + 1"},{"text":"8"},{"text":"2π + 2"}],"condition":{"src":"assets/grades-9-10/2005/task-13.svg","width":202,"height":135,"alt":"Верхняя полуокружность над двумя нижними. Область между дугами заштрихована, точки A и B над центрами E и F"},"answer":3,"points":4,"review":[{"title":"Решение","text":"Над горизонтальным отрезком AB лежит полукруг площади 2π. Под ним в прямоугольнике ABEF область дополняется до прямоугольника двумя четвертями кругов радиуса 2."},{"title":"Ответ","text":"У двух четвертей вместе тоже площадь 2π, поэтому эти площади сокращаются. Остаётся площадь прямоугольника 4 × 2 = 8."}],"keyNote":null},{"number":14,"title":"Значения выражений","question":"Числа a и b таковы, что 4 ≤ a ≤ 6, 1 ≤ b ≤ 2. Какое из следующих чисел обязательно меньше 9?","options":[{"text":"2a − 3b"},{"text":"a + 2b"},{"text":"3a − b"},{"text":"8b − 2a"},{"text":"13b − a"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Выражение 8b − 2a максимально при b = 2 и a = 4. Даже тогда оно равно 16 − 8 = 8, меньше 9."},{"title":"Ответ","text":"Остальные выражения могут достигать соответственно 9, 10, 17 и 22. Для каждого достаточно взять подходящие крайние значения a и b."}],"keyNote":null},{"number":15,"title":"Кубик на клетчатой дорожке","question":"Игральный кубик, сумма очков на противоположных гранях которого равна 7, прокатили по клетчатой дорожке. Начальное положение кубика и дорожка изображены на рисунке. Сколько очков оказалось на верхней грани кубика в конце пути?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-9-10/2005/task-15.svg","width":222,"height":126,"alt":"На начальном кубике сверху три точки, спереди две, справа одна. Рядом клетчатая дорожка с поворотами"},"answer":2,"points":4,"review":[{"title":"Решение","text":"Дорожка состоит из двух перекатов вправо, двух к нам и ещё двух вправо."},{"title":"Ответ","text":"Любые два переката в одном направлении меняют верхнюю грань на противоположную. Три такие пары дают последовательность 3, 4, 3, 4. Наверху четыре точки."}],"keyNote":null},{"number":16,"title":"Фигура из треугольников","question":"Если многоугольник (возможно, невыпуклый) составлен из 8 одинаковых правильных треугольников, то он не может быть","options":[{"text":"семиугольником"},{"text":"шестиугольником"},{"text":"трапецией"},{"text":"ромбом"},{"text":"треугольником"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"У равностороннего треугольника, составленного из маленьких равносторонних треугольников, сторона состоит из целого числа их сторон. Если их k, то площадь большого в k² раз больше площади одного маленького."},{"title":"Ответ","text":"Число 8 не является квадратом целого k. Поэтому из восьми деталей равностороннего треугольника не выйдет."}],"keyNote":null},{"number":17,"title":"Сумма трёх простых чисел","question":"Пусть p — наименьшее простое число, которое равно сумме трех различных простых чисел: p = p₁ + p₂ + p₃. Тогда произведение p₁ · p₂ · p₃ равно","options":[{"text":"30"},{"text":"165"},{"text":"105"},{"text":"231"},{"text":"385"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Число 2 нельзя взять в такую сумму, поскольку вместе с двумя нечётными простыми оно дало бы чётное число больше 2."},{"title":"Ответ","text":"Три наименьших разных нечётных простых дают 3 + 5 + 7 = 15, оно составное. Следующая по величине сумма 3 + 5 + 11 = 19 уже проста. Произведение равно 165."}],"keyNote":null},{"number":18,"title":"Углы вписанной трапеции","question":"Трапеция ABCD с основанием AB вписана в окружность. Угол ADB равен 65°, а угол DBC равен 35°. Тогда угол A равен","options":[{"text":"70°"},{"text":"75°"},{"text":"80°"},{"text":"105°"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-9-10/2005/task-18.svg","width":206,"height":190,"alt":"Вписанная трапеция ABCD с диагональю DB и отмеченными углами 65° и 35°"},"answer":1,"points":4,"review":[{"title":"Решение","text":"Вписанный угол ADB стягивает дугу AB величиной 130°, а угол DBC — дугу DC величиной 70°."},{"title":"Ответ","text":"Вписанная трапеция равнобедренная, значит, дуги AD и BC равны. Каждая равна (360° − 130° − 70°)/2 = 80°. Угол A стягивает дугу DCB величиной 150° и равен 75°."}],"keyNote":null},{"number":19,"title":"Самая тяжёлая гиря","question":"Имеется набор гирь, в котором самая тяжелая гиря в 5 раз тяжелее среднего веса всех гирь. Чему не может равняться количество гирь в наборе?","options":[{"text":"15"},{"text":"11"},{"text":"8"},{"text":"6"},{"text":"4"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Пусть средний вес равен m, а гирь n. Их общий вес nm, а одна гиря весит 5m."},{"title":"Ответ","text":"Есть и другие гири положительного веса, поэтому nm > 5m и n > 5. Четыре гири невозможны."}],"keyNote":null},{"number":20,"title":"Середины отрезков в кубе","question":"Каждая пара вершин куба соединена отрезком. Сколько различных середин у всех этих отрезков?","options":[{"text":"8"},{"text":"12"},{"text":"18"},{"text":"19"},{"text":"28"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Двенадцать рёбер имеют двенадцать различных середин. Ещё по две диагонали у каждой из шести граней делят одну середину."},{"title":"Ответ","text":"Четыре пространственные диагонали имеют общую середину — центр куба. Всего 12 + 6 + 1 = 19 точек."}],"keyNote":null},{"number":21,"title":"Расстояния на Земле","question":"Пусть S — площадь поверхности Земли, а S₀ — площадь той ее части, точки которой ближе к Петербургу, чем к центру Земли. Тогда","options":[{"text":"S₀/S > 1/2"},{"text":"S₀/S = 1/2"},{"text":"1/3 < S₀/S < 1/2"},{"text":"S₀/S = 1/3"},{"text":"S₀/S < 1/3"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Расстояние любой точки поверхности до центра равно радиусу R. Хорда от Петербурга до точки короче R тогда и только тогда, когда центральный угол меньше 60°."},{"title":"Ответ","text":"Эти точки образуют сферическую шапку высоты R(1 − cos 60°) = R/2. Её площадь 2πR × R/2 составляет четверть площади сферы. Это меньше 1/3."}],"keyNote":null},{"number":22,"title":"Две стороны и угол","question":"Сколько существует треугольников, у которых одна из сторон равна 3 см, другая — 4 см, и один из углов равен 10°?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если угол 10° заключён между сторонами 3 и 4, треугольник один. Иначе применим теорему синусов."},{"title":"Проверка","text":"У 10° напротив стороны 4 синус угла против стороны 3 равен (3/4)sin 10°. Подходит только острый угол меньше 10°, его дополнение до 180° слишком велико."},{"title":"Ответ","text":"У 10° напротив стороны 3 второй синус (4/3)sin 10°. Соответствующий острый угол больше 10°, значит, здесь допустим и он, и его дополнение до 180°. Итого 1 + 1 + 2 = 4 треугольника."}],"keyNote":null},{"number":23,"title":"График новой зависимости","question":"На чертеже справа показана зависимость y − x от y + x. На каком из графиков (A)–(E) изображена зависимость y от x?","options":[{"image":"assets/grades-9-10/2005/task-23-answer-1.svg","description":"Горизонтальная прямая выше начала координат"},{"image":"assets/grades-9-10/2005/task-23-answer-2.svg","description":"Возрастающая наклонная прямая"},{"image":"assets/grades-9-10/2005/task-23-answer-3.svg","description":"Пологая убывающая прямая"},{"image":"assets/grades-9-10/2005/task-23-answer-4.svg","description":"Крутая убывающая прямая"},{"image":"assets/grades-9-10/2005/task-23-answer-5.svg","description":"Горизонтальная прямая ниже начала координат"}],"condition":{"src":"assets/grades-9-10/2005/task-23.svg","width":154,"height":165,"alt":"Оси y + x по горизонтали и y − x по вертикали. Прямая проходит через начало координат и поднимается вправо"},"answer":3,"points":5,"review":[{"title":"Решение","text":"На рисунке зависимость имеет вид y − x = k(y + x), где k > 1. Действительно, луч поднимается круче диагонали с равными приращениями осей."},{"title":"Ответ","text":"Получаем y = −(k + 1)x/(k − 1). Это убывающая прямая через начало координат, более крутая, чем y = −x. Подходит D."}],"keyNote":null},{"number":24,"title":"Путь гусеницы","question":"Гусеница выползла из домика в полдень и ползет по лугу, поворачивая через каждый час на 90° направо или налево. За первый час она проползла 1 м, за второй — 2 м, и т. д. На каком наименьшем расстоянии от домика она могла оказаться в 10 часов вечера?","options":[{"text":"0 м"},{"text":"1 м"},{"text":"2 м"},{"text":"√5 м"},{"text":"√61 м"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"По одной оси идут отрезки 1, 3, 5, 7 и 9, по другой 2, 4, 6, 8 и 10. Первая координата нечётна. Вторая имеет остаток 2 по модулю 4, поскольку смена знака чётного слагаемого меняет сумму на число, кратное 4."},{"title":"Ответ","text":"Значит, абсолютные значения координат не меньше 1 и 2. Если обратить знаки у 3 и 9 на первой оси и у 4 и 10 на второй, получатся именно 1 и 2. Расстояние равно √5 м."}],"keyNote":null},{"number":25,"title":"Квадрат из факториалов","question":"По определению, n! = 1 · 2 · 3 · … · n. Какой сомножитель нужно вычеркнуть из произведения 1! · 2! · 3! · 4! · … · 100!, чтобы оставшееся произведение стало квадратом некоторого натурального числа?","options":[{"text":"13!"},{"text":"42!"},{"text":"47!"},{"text":"50!"},{"text":"это невозможно"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"В произведении от 1! до 100! число k встречается 101 − k раз. Нечётно это число повторений только для чётных k."},{"title":"Ответ","text":"Если выделить квадрат, остаётся 2 × 4 × … × 100 = 2⁵⁰·50!. Множитель 2⁵⁰ сам квадрат. Значит, достаточно вычеркнуть 50!."}],"keyNote":null},{"number":26,"title":"Точки по сторонам параболы","question":"Каждая парабола y = ax² + bx + c разбивает плоскость на две части. Если две точки попадают в разные части, то будем говорить, что парабола разделяет эти точки. Какие две точки не могут быть разделены никакой параболой вида y = ax² + x, a > 0?","options":[{"text":"(−1; 1) и (1; −1)"},{"text":"(−1; 0) и (1; 0)"},{"text":"(−8; 0) и (−1; 0)"},{"text":"(3; 0) и (5; 0)"},{"text":"все пары A–D могут быть разделены"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"При x > 0 выражение ax² + x положительно для всякого a > 0. Поэтому точки (3; 0) и (5; 0) обе всегда ниже параболы."},{"title":"Ответ","text":"Другие пары разделимы. Для A подойдёт a = 1, для B и C — a = 1/2. Неподходящая пара указана в D."}],"keyNote":null},{"number":27,"title":"Красные и синие клетки","question":"На белой клетчатой доске 10×10 Вася закрасил 10 клеток синим цветом, а несколько других клеток — красным цветом. Оказалось, что никакие две клетки красного и синего цвета не имеют общей стороны. Какое наименьшее число клеток могли остаться незакрашенными?","options":[{"text":"10"},{"text":"7"},{"text":"6"},{"text":"5"},{"text":"3"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Белыми должны остаться все клетки, которые соседствуют с синими и сами не синие. Сдвинем синие в каждой строке к левому краю. Число клеток в объединении синих и их соседей не может вырасти. В каждой строке после сдвига всё объединение — отрезок длиной, равной наибольшему из вклада своей и двух соседних строк. До сдвига объединение не могло быть меньше ни одного из этих вкладов."},{"title":"Проверка","text":"Затем сдвигаем синие в каждом столбце вверх по тому же правилу. Длины столбцов невозрастают слева направо, поэтому получаем фигуру с невозрастающими длинами строк. В ней если не меньше четырёх непустых строк, у каждой есть правый сосед, а под нижней строкой ещё хотя бы один. Аналогично для четырёх столбцов. Десять клеток не входят в 3 × 3, а полная строка или столбец сразу даёт десять соседей. Значит, белых не меньше пяти."},{"title":"Ответ","text":"В верхнем левом углу возьмём синие строки длины 4, 3, 2 и 1. Белые клетки вдоль их внешней границы образуют следующую диагональ длиной пять. Остальные клетки можно покрасить красным."}],"keyNote":null},{"number":28,"title":"Набор четырёх чисел","question":"Про набор чисел a + 2, −2/a, 6, a² известно, что два из этих чисел равны, а еще одно ровно вдвое больше их. Тогда","options":[{"text":"a + 2 = −2/a"},{"text":"−2/a = 6"},{"text":"−2/a = a²"},{"text":"a² = a + 2"},{"text":"это невозможно"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если равны a + 2 и −2/a, получилось бы (a + 1)² + 1 = 0, что невозможно. Если одна из одинаковых величин равна 6, то при a = 4, −1/3 или ±√6 ни одна из остальных не равна 12."},{"title":"Проверка","text":"Если −2/a = a², то a = −∛2. Удвоенное общее значение лежит между 3 и 4, тогда как оставшиеся числа 6 и 2 − ∛2 лежат вне этого промежутка."},{"title":"Ответ","text":"Остаётся a² = a + 2, то есть a = 2 или a = −1. При −1 эти два числа равны 1, а −2/a = 2 составляет ровно вдвое больше."}],"keyNote":null},{"number":29,"title":"Три графика функций","question":"На картинке изображены графики функций f(x), g(x) и еще одной. Какой?","options":[{"text":"f(x) + g(x)"},{"text":"f(x) − g(x)"},{"text":"f(x) · g(x)"},{"text":"f(x)/g(x)"},{"text":"−f(x) · g(x)"}],"condition":{"src":"assets/grades-9-10/2005/task-29.svg","width":189,"height":219,"alt":"Три кривые на общих осях: верхняя из начала координат, нижняя с отрицательным начальным значением и кривая-дуга под осью x"},"answer":2,"points":5,"review":[{"title":"Решение","text":"У верхней функции нуль на левом конце, у нижней — на правом. Между концами верхняя положительна, нижняя отрицательна."},{"title":"Ответ","text":"Их произведение отрицательно между концами и равно нулю на обоих концах, как третья кривая. Сумма и разность не обращаются в нуль на обоих концах, частное не определено на одном из них, а минус произведения положителен между ними."}],"keyNote":null},{"number":30,"title":"Центры двух окружностей","question":"Найдите тупой угол треугольника, в котором центры вписанной и описанной окружностей симметричны относительно некоторой стороны этого треугольника.","options":[{"text":"100°"},{"text":"108°"},{"text":"120°"},{"text":"136°"},{"text":"150°"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Центры лежат на перпендикуляре к стороне, проходящем через её середину. Поскольку там лежит и центр вписанной окружности, углы у концов стороны равны. Треугольник равнобедренный."},{"title":"Проверка","text":"При половине основания a, боковой стороне s и высоте h радиус вписанной окружности равен ah/(a+s). Расстояние от центра описанной окружности до основания с внешней стороны равно (a² − h²)/(2h). Приравниваем их."},{"title":"Ответ","text":"Пусть t = s/a. Из h²/a² = t² − 1 получается 2(t−1) = 2−t² и t = √5−1. Косинус угла при основании a/s = (1 + √5)/4, значит, это 36°. Тупой угол равен 108°."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2005-9-10"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2005] ?? []).find(edition => edition.id === "2005-9-10")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
